// dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>(); // row index for A,Q  (0..M-1)
constexpr auto j_vec = noarr::vector<'j'>(); // column index for A,Q,R (0..N-1)
constexpr auto k_vec = noarr::vector<'k'>(); // row index for R     (0..N-1)

// layout tuning: separate layout description from element type
struct tuning {
	// A, Q: M x N, indexed as A[i][j], Q[i][j]
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec); // dims: 'i', 'j'
	DEFINE_PROTO_STRUCT(q_layout, j_vec ^ i_vec); // dims: 'i', 'j'

	// R: N x N, indexed as R[k][j]
	DEFINE_PROTO_STRUCT(r_layout, j_vec ^ k_vec); // dims: 'k', 'j'
} tuning;

// -----------------------------------------------------------------------------
// Array initialization
// -----------------------------------------------------------------------------
void init_array(auto A, auto R, auto Q) {
	// A: i x j
	// R: k x j
	// Q: i x j
	using namespace noarr;

	// lengths (problem sizes)
	const auto m_len = A | get_length<'i'>(); // M
	const auto n_len = A | get_length<'j'>(); // N

	// Initialize A and Q
	// for (i = 0; i < m; i++)
	//   for (j = 0; j < n; j++) {
	//     A[i][j] = ((( (i*j) % m ) / m )*100) + 10;
	//     Q[i][j] = 0.0;
	//   }
	traverser(A, Q).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		num_t val = (num_t)(((i * j) % m_len)) / (num_t)m_len;
		val = val * (num_t)100 + (num_t)10;
		A[state] = val;
		Q[state] = (num_t)0;
	});

	// Initialize R
	// for (i = 0; i < n; i++)
	//   for (j = 0; j < n; j++)
	//     R[i][j] = 0.0;
	traverser(R).for_each([=](auto state) {
		R[state] = (num_t)0;
	});
}

// -----------------------------------------------------------------------------
// Main computational kernel: Modified Gram-Schmidt
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_gramschmidt(auto A, auto R, auto Q) {
	// A: i x j  (M x N)
	// R: k x j  (N x N)
	// Q: i x j  (M x N)
	using namespace noarr;

	const auto n_len = A | get_length<'j'>(); // N

	#pragma scop
	// Outer loop over k: 0 .. N-1
	// We iterate k using the 'k' dimension of R (its row index).
	traverser(R).template for_dims<'k'>([=](auto trav_k) {
		// trav_k is a traverser with dimension 'k' fixed to a specific value
		auto state_k = trav_k.state();
		auto k_idx = get_index<'k'>(state_k);

		// -----------------------------------------------------------------
		// nrm = Σ_i A[i][k]^2
		// -----------------------------------------------------------------
		num_t nrm = (num_t)0;

		// View of column k of A: fix 'j' = k
		auto A_col_k = A ^ noarr::fix<'j'>(k_idx); // dims: 'i'

		traverser(A_col_k).for_each([&](auto state_i) {
			num_t a_ik = A_col_k[state_i];
			nrm += a_ik * a_ik;
		});

		// R[k][k] = sqrt(nrm)
		num_t r_kk = std::sqrt(nrm);

		// View of row k of R: fix 'k' = k
		auto R_row_k = R ^ noarr::fix<'k'>(k_idx); // dims: 'j'
		R_row_k.template at<'j'>(k_idx) = r_kk;

		// -----------------------------------------------------------------
		// Q[i][k] = A[i][k] / R[k][k]  for all i
		// -----------------------------------------------------------------
		auto Q_col_k = Q ^ noarr::fix<'j'>(k_idx); // dims: 'i'

		traverser(A_col_k, Q_col_k).for_each([&](auto state_i) {
			Q_col_k[state_i] = A_col_k[state_i] / r_kk;
		});

		// -----------------------------------------------------------------
		// for (j = k+1; j < N; j++)
		//   R[k][j] = Σ_i Q[i][k]*A[i][j];
		//   A[i][j] -= Q[i][k]*R[k][j];
		// -----------------------------------------------------------------
		if (k_idx + 1 >= n_len)
			return; // no columns j > k to process

		// Slice of the 'j' dimension: j = k+1 .. N-1
		auto j_slice = noarr::slice<'j'>(k_idx + 1, n_len - (k_idx + 1));

		// Iterate over all j > k using the sliced view of R_row_k
		traverser(R_row_k ^ j_slice).for_each([&](auto state_j) {
			auto j_idx = get_index<'j'>(state_j);

			// Compute R[k][j] as the dot product over i:
			//   R[k][j] = Σ_i Q[i][k] * A[i][j]
			num_t r_kj = (num_t)0;

			// View of column j of A: fix 'j' = j_idx
			auto A_col_j = A ^ noarr::fix<'j'>(j_idx); // dims: 'i'

			traverser(Q_col_k, A_col_j).for_each([&](auto state_i) {
				r_kj += Q_col_k[state_i] * A_col_j[state_i];
			});

			// Store R[k][j]
			R_row_k.template at<'j'>(j_idx) = r_kj;

			// Update A[i][j] = A[i][j] - Q[i][k] * R[k][j]  for all i
			traverser(A_col_j, Q_col_k).for_each([&](auto state_i) {
				A_col_j[state_i] -= Q_col_k[state_i] * r_kj;
			});
		});
	});
	#pragma endscop
}

} // namespace

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// set lengths for all relevant dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(n);

	// allocate bags
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto R = noarr::bag(noarr::scalar<num_t>() ^ tuning.r_layout ^ set_lengths);
	auto Q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), R.get_ref(), Q.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_gramschmidt(A.get_ref(), R.get_ref(), Q.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results to prevent dead-code elimination
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);

		// print R (N x N), hoist row dimension 'k'
		noarr::serialize_data(std::cerr, R.get_ref() ^ noarr::hoist<'k'>());

		// print Q (M x N), hoist row dimension 'i'
		noarr::serialize_data(std::cerr, Q.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
