// QR Decomposition with Modified Gram Schmidt.
[[gnu::flatten, gnu::noinline]]
void kernel_gramschmidt(auto A, auto R, auto Q) {
	using namespace noarr;

	#pragma scop
	// Outer loop over k = 0 .. N-1 (column index)
	traverser(A).template for_dims<'j'>([&](auto trav_k) {
		// trav_k has dimension 'j' fixed to the current column k
		auto state_k = trav_k.state();
		auto k = get_index<'j'>(state_k);

		// nrm = sum_i A[i][k]^2
		num_t nrm = SCALAR_VAL(0.0);

		trav_k.template for_each<'i'>([&](auto s_ik) {
			nrm += A[s_ik] * A[s_ik];
		});

		// R[k][k] = sqrt(nrm)
		auto s_kk = noarr::idx<'k', 'j'>(k, k);
		R[s_kk] = SQRT_FUN(nrm);

		// Q[i][k] = A[i][k] / R[k][k]
		trav_k.template for_each<'i'>([&](auto s_ik) {
			Q[s_ik] = A[s_ik] / R[s_kk];
		});

		// Inner loop over j = k+1 .. N-1 (columns to the right of k)
		traverser(A).template for_dims<'j'>([&](auto trav_j) {
			// trav_j has dimension 'j' fixed to the current column j
			auto state_j = trav_j.state();
			auto j = get_index<'j'>(state_j);

			if (j <= k)
