			trav_j.template for_each<'i'>([&](auto s_ij) {
				auto s_ik = s_ij.template with<noarr::index_in<'j'>>(k);
				A[s_ij] = A[s_ij] - Q[s_ik] * R[s_kj];
			});
		});
	});
	#pragma endscop
}

