		// k-th column views of A and Q (A[:, k], Q[:, k])
		auto A_col_k = A ^ noarr::fix<'j'>(k);
		auto Q_col_k = Q ^ noarr::fix<'j'>(k);

		noarr::traverser(A_col_k).for_each([&](auto state) {
			num_t a_ik = A_col_k[state];
			nrm += a_ik * a_ik;
		});

		// R[k][k] = sqrt(nrm);
		num_t r_kk = std::sqrt(nrm);
		R[noarr::idx<'k', 'j'>(k, k)] = r_kk;

		// for (i = 0; i < m; i++)
		//   Q[i][k] = A[i][k] / R[k][k];
		noarr::traverser(A_col_k, Q_col_k).for_each([&](auto state) {
			Q_col_k[state] = A_col_k[state] / r_kk;
		});

		// for (j = k + 1; j < n; j++) {
		for (std::size_t j = k + 1; j < n; j++) {
			//   R[k][j] = 0.0;
			//   for (i = 0; i < m; i++)
			//     R[k][j] += Q[i][k] * A[i][j];
			//   for (i = 0; i < m; i++)
			//     A[i][j] = A[i][j] - Q[i][k] * R[k][j];
			// }

			num_t r_kj = (num_t)0.0;

			// j-th column view of A: A[:, j]
			auto A_col_j = A ^ noarr::fix<'j'>(j);

			// Accumulate R[k][j]
			noarr::traverser(Q_col_k, A_col_j).for_each([&](auto state) {
				r_kj += Q_col_k[state] * A_col_j[state];
			});

			R[noarr::idx<'k', 'j'>(k, j)] = r_kj;

			// Update A[:, j]
			noarr::traverser(Q_col_k, A_col_j).for_each([&](auto state) {
				A_col_j[state] = A_col_j[state] - Q_col_k[state] * r_kj;
			});
		}
	}
	#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// set lengths for all dimensions used
	auto set_lengths =
		noarr::set_length<'i'>(m) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(n);

	// allocate bags
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto R = noarr::bag(noarr::scalar<num_t>() ^ tuning.r_layout ^ set_lengths);
	auto Q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref(), R.get_ref(), Q.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_gramschmidt(A.get_ref(), R.get_ref(), Q.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optional: print results to stderr (R then Q) to prevent dead-code elimination
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, R.get_ref() ^ noarr::hoist<'k'>());
		noarr::serialize_data(std::cerr, Q.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "gramschmidt.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: i x k  (M x N)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// Q: i x k  (M x N)
	DEFINE_PROTO_STRUCT(q_layout, k_vec ^ i_vec);
	// R: k x j  (N x N), first index is k, second is j
	DEFINE_PROTO_STRUCT(r_layout, j_vec ^ k_vec);
} tuning;

// initialization function
void init_array(auto A, auto R, auto Q) {
	// A: i x k  (M x N)
	// Q: i x k  (M x N)
	// R: k x j  (N x N)
	using namespace noarr;

	// lengths (problem sizes)
	auto m = A | get_length<'i'>();
	auto m_val = static_cast<num_t>(m);

	// Initialize A and Q
	traverser(A, Q).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);

		// A[i][k] = (((DATA_TYPE) ((i*j) % m) / m )*100) + 10;
		// Here, the second index in C (j) is the same logical column dimension as 'k'.
		num_t val = (static_cast<num_t>((i * k) % m) / m_val) * static_cast<num_t>(100.0) + static_cast<num_t>(10.0);

		A[state] = val;
		Q[state] = SCALAR_VAL(0.0);
	});

	// Initialize R to 0
	traverser(R).for_each([=](auto state) {
		R[state] = SCALAR_VAL(0.0);
	});
}

// computation kernel
/* QR Decomposition with Modified Gram Schmidt:
   http://www.inf.ethz.ch/personal/gander/ */
[[gnu::flatten, gnu::noinline]]
void kernel_gramschmidt(auto A, auto R, auto Q) {
	// A: i x k  (M x N)
	// Q: i x k  (M x N)
	// R: k x j  (N x N)
	using namespace noarr;

	// Outer loop over k (0 .. N-1)
	#pragma scop
	traverser(A, R, Q).template for_dims<'k'>([&](auto trav_k) {
		auto state_k = trav_k.state();
		auto k_idx = get_index<'k'>(state_k);

		// nrm = 0.0;
		num_t nrm = SCALAR_VAL(0.0);

		// for (i = 0; i < M; i++)
		//   nrm += A[i][k] * A[i][k];
		trav_k.template for_each<'i'>([&](auto state_ik) {
			// state_ik contains 'i' and 'k' (and possibly 'j', which A ignores)
			num_t aik = A[state_ik];
			nrm += aik * aik;
		});

		// R[k][k] = SQRT_FUN(nrm);
		auto state_kk = state_k.template with<index_in<'j'>>(k_idx);
		R[state_kk] = SQRT_FUN(nrm);

		const num_t r_kk = R[state_kk];

		// for (i = 0; i < M; i++)
		//   Q[i][k] = A[i][k] / R[k][k];
		trav_k.template for_each<'i'>([&](auto state_ik) {
			Q[state_ik] = A[state_ik] / r_kk;
		});

		// for (j = k + 1; j < N; j++) { ... }
		// We iterate all j, then skip j <= k to preserve semantics.
		trav_k.template for_dims<'j'>([&](auto trav_kj) {
			auto state_kj = trav_kj.state();
			auto j_idx = get_index<'j'>(state_kj);
			auto k_idx_local = get_index<'k'>(state_kj);

			if (j_idx <= k_idx_local)
				return; // corresponds to "for (j = k+1; ...)"

			// R[k][j] = 0.0;
			R[state_kj] = SCALAR_VAL(0.0);
			num_t &R_kj = R[state_kj];

			// for (i = 0; i < M; i++)
			//   R[k][j] += Q[i][k] * A[i][j];
			trav_kj.for_each([&](auto state) {
				// state has indices 'i', 'k', 'j':
				//   for Q we want column k (current k),
				//   for A we want column j (current j_idx).
				auto state_Q_ik = state; // uses 'i' and 'k' (k = k_idx_local)
				auto state_A_ij = state.template with<index_in<'k'>>(j_idx); // set column index to j

				R_kj += Q[state_Q_ik] * A[state_A_ij];
			});

			// for (i = 0; i < M; i++)
			//   A[i][j] = A[i][j] - Q[i][k] * R[k][j];
			trav_kj.for_each([&](auto state) {
				auto state_Q_ik = state; // 'i', 'k' (k = k_idx_local)
				auto state_A_ij = state.template with<index_in<'k'>>(j_idx);

				A[state_A_ij] = A[state_A_ij] - Q[state_Q_ik] * R_kj;
			});
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// data
	auto set_lengths =
		noarr::set_length<'i'>(m) ^
		noarr::set_length<'k'>(n) ^
		noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto R = noarr::bag(noarr::scalar<num_t>() ^ tuning.r_layout ^ set_lengths);
	auto Q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), R.get_ref(), Q.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_gramschmidt(A.get_ref(), R.get_ref(), Q.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent DCE), if requested
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// Print R row-major (k as outer)
		noarr::serialize_data(std::cerr, R.get_ref() ^ noarr::hoist<'k'>());
		// Print Q row-major (i as outer)
		noarr::serialize_data(std::cerr, Q.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
